# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NECASETTEN TAHÂRET VE HADESTEN TAHÂRET (2.1 &amp; 2.2)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Necasetten Tahâret (Maddi Temizlik)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Gözle görülen maddi kirlerden arınmaktır</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Bedenin temiz tutulması</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Elbisenin temiz tutulması (Müddessir 4)</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• İbadet edilecek yerin (mekânın) temizliği</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Çevrenin ve su kaynaklarının korunması</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#334155">Namazın dışındaki (hazırlık) farzlarındandır</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Hadesten Tahâret (Hükmî Temizlik)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Gözle görülmeyen hükmî kirlilikten (abdestsizlik</text>\n  <text x="520" y="116" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">  ve cünüplük hâlinden) ibadet niyetiyle arınmaktır</text>\n  <text x="520" y="144" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Küçük Hades: Abdestsizlik ➔ Abdest ile giderilir</text>\n  <text x="520" y="170" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Büyük Hades: Boy abdestsizliği ➔ Gusül ile giderilir</text>\n  <text x="520" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Su bulunmadığında ➔ Teyemmüm ile giderilir</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#166534">Dayanağı: Mâide Suresi 6. Ayet-i Kerime</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ABDESTİN FARZLARI (MÂİDE SURESİ 6. AYET) VE SÜNNETLERİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Abdestin 4 Farzı (Kuru Yer Kalmamalı!)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">1. Yüzü yıkamak (Saç bitiminden çene altına)</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">2. Elleri dirseklerle beraber yıkamak</text>\n  <text x="180" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">3. Başın dörtte birini mesh etmek (ıslak elle)</text>\n  <text x="180" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">4. Ayakları topuklarla (aşık kemikleriyle) yıkamak</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Namaz kılmak ve Kâbe\'yi tavaf için farzdır</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Abdestin Sünnetleri ve Bozan Durumlar</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Sünnetleri: Niyet ve Besmele ile başlamak, elleri</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#581c87">bileklere kadar yıkamak, ağız ve burnu 3 kez</text>\n  <text x="520" y="136" text-anchor="middle" font-size="11" fill="#581c87">yıkamak, kulakları mesh etmek, sıraya uymak</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Bozan Durumlar: Tuvalet ihtiyacı, vücuttan kan</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11" fill="#581c87">veya irin çıkıp dağılması, ağız dolusu kusmak,</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" fill="#581c87">uyumak, bayılmak, namazda sesli gülmek (kahkaha)</text>\n  <text x="520" y="226" text-anchor="middle" font-size="10" fill="#475569">Ağlamak veya tırnak kesmek abdesti bozmaz!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GUSÜL (BOY ABDESTİ) VE TEYEMMÜMÜN FARZLARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Guslün (Boy Abdestinin) 3 Farzı</text>\n  <text x="180" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">1. Mazmaza: Ağza bol su alıp boğaza kadar</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11" fill="#881337">   çalkalayarak yıkamak</text>\n  <text x="180" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">2. İstinşak: Burna genze kadar su çekip yıkamak</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">3. Bütün bedeni kuru yer kalmayacak şekilde</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11" fill="#881337">   tepeden tırnağa yıkamak</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Cuma ve bayram günleri gusletmek sünnettir</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Teyemmümün 2 Farzı (Toprakla Temizlik)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" fill="#164e63">Su bulunmadığında veya suyu kullanmaya sağlık</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#164e63">engeli olduğunda temiz toprak cinsiyle alınır:</text>\n  <text x="520" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">1. Niyet etmek (Teyemmümde niyet farzdır!)</text>\n  <text x="520" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">2. Elleri temiz toprağa vurup yüzü, ikinci kez</text>\n  <text x="520" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">   vurup kolları dirseklerle birlikte mesh etmek</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Su bulunduğu anda teyemmüm bozulur!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
